+    <script>
+      (function () {
+        const body = document.body;
+        const hamburger = document.getElementById("hamburger");
+        const overlay = document.getElementById("mobile-menu");
+        const closeBtn = document.getElementById("close-menu");
+        const focusableSelector =
+          "a[href], button:not([disabled]), [tabindex]:not([tabindex='-1'])";
+        let lastActive = null;
+
+        function openMenu() {
+          lastActive = document.activeElement;
+          body.classList.add("menu-open");
+          hamburger.setAttribute("aria-expanded", "true");
+
+          const first = overlay.querySelector(focusableSelector);
+          if (first) first.focus();
+        }
+
+        function closeMenu() {
+          body.classList.remove("menu-open");
+          hamburger.setAttribute("aria-expanded", "false");
+          if (lastActive && typeof lastActive.focus === "function") lastActive.focus();
+        }
+
+        hamburger.addEventListener("click", function () {
+          if (body.classList.contains("menu-open")) closeMenu();
+          else openMenu();
+        });
+
+        closeBtn.addEventListener("click", closeMenu);
+
+        overlay.addEventListener("click", function (e) {
+          if (e.target === overlay) closeMenu();
+        });
+
+        overlay.addEventListener("click", function (e) {
+          const target = e.target;
+          if (target && target.matches && target.matches("[data-close-menu]")) {
+            closeMenu();
+          }
+        });
+
+        document.addEventListener("keydown", function (e) {
+          if (!body.classList.contains("menu-open")) return;
+          if (e.key === "Escape") {
+            e.preventDefault();
+            closeMenu();
+            return;
+          }
+
+          if (e.key !== "Tab") return;
+          const focusables = Array.from(overlay.querySelectorAll(focusableSelector));
+          if (!focusables.length) return;
+
+          const first = focusables[0];
+          const last = focusables[focusables.length - 1];
+          const active = document.activeElement;
+
+          if (e.shiftKey && active === first) {
+            e.preventDefault();
+            last.focus();
+          } else if (!e.shiftKey && active === last) {
+            e.preventDefault();
+            first.focus();
+          }
+        });
+
+        // Make carousel nicer on desktop: shift-wheel scroll sideways.
+        const carousel = document.getElementById("news-carousel");
+        if (carousel) {
+          carousel.addEventListener(
+            "wheel",
+            function (e) {
+              const absX = Math.abs(e.deltaX);
+              const absY = Math.abs(e.deltaY);
+              if (absY > absX) {
+                e.preventDefault();
+                carousel.scrollLeft += e.deltaY;
+              }
+            },
+            { passive: false }
+          );
+        }
+      })();
+    </script>
